  `sid` int DEFAULT NULL COMMENT '所属店铺编号',
  `state` int DEFAULT NULL COMMENT '图书状态',
  `kid` int DEFAULT NULL COMMENT '所属分类编号',
  `content` varchar(255) DEFAULT NULL COMMENT '分类内容',
  PRIMARY KEY (`bid`),
  KEY `idx_book_sid` (`sid`),
  KEY `idx_book_kid` (`kid`),
